import {PROFILES,clone} from './model.mjs';
export const pageHeight=d=>Math.max(1431,Math.min(20000,Number(d?.pageHeight)||1431));
function wrappedLines(text,width,size,family='Arial'){const context=globalThis.document?.createElement?.('canvas')?.getContext?.('2d');if(context)context.font=`${size}px ${family}`;const measure=t=>context?context.measureText(t).width:t.length*size*.58;let lines=0;for(const paragraph of String(text||'').split('\n')){let current='';lines++;for(const word of paragraph.split(/\s+/)){if(current&&measure(current+' '+word)>width){lines++;current=word;}else current+=(current?' ':'')+word;}}return lines;}
export function requiredHeight(b,doc,skills=[]){const style=b.textStyle||{},size=Number(style.size)||b.font||24,padding=Number(style.padding)||0,lineHeight=Number(style.lineHeight)||1.42,w=Math.max(30,b.w-padding*2),bodyHeight=t=>Math.ceil(wrappedLines(t,w,size,style.family)*size*lineHeight+padding*2+12);let h=b.h;
 if(['text','ability','profile','equipment'].includes(b.type)){const body=b.type==='ability'?doc.abilities.find(a=>a.id===b.ref)?.body||'':b.type==='profile'?b.body??PROFILES[doc.profile][1]:b.type==='equipment'?doc.equipment:b.body||'';h=bodyHeight(body)+(b.part==='content'?0:53);}
 else if(b.type==='rituals'){h=(b.part==='content'?0:56)+doc.rituals.reduce((n,r)=>n+Math.max(50,bodyHeight(r.summary||r.body)+Math.max(25,size+1)+16),0);}
 else if(b.type==='ritualPart'){const r=doc.rituals.find(r=>r.id===b.ref);h=bodyHeight(r?.[b.field||'body']||r?.body||'')+(b.showTitle?53:0);}
 else if(b.type==='skills'){const count=skills.length||26,columns=Math.max(1,Number(b.columns)||1);h=(b.part==='content'?11:65)+Math.ceil(count/columns)*(size*1.5+(Number(b.rowGap)||0));}
 else if(b.type==='attributes')h=Math.max(225,size*6.5);
 return Math.max(25,Math.ceil(h));}
export function flowBlocks(doc,blocks,{columns=2,startY=300,gap=28,margin=120,skills=[]}={}){const width=(1920-2*margin-gap*(columns-1))/columns,heights=Array(columns).fill(startY),warnings=[];for(const b of blocks){const col=heights.indexOf(Math.min(...heights));b.x=margin+col*(width+gap);b.y=heights[col];b.w=width;const required=requiredHeight(b,doc,skills);b.h=Math.max(b.type==='portrait'?350:25,required);if(b.h>4000){warnings.push({id:b.id,message:'Bloco exige mais de 4000 px. Divida o conteúdo em partes.'});b.h=4000;}b.autoFit=false;heights[col]=b.y+b.h+gap;}const needed=Math.ceil(Math.max(...heights)+80);doc.pageHeight=Math.max(pageHeight(doc),Math.min(20000,needed));if(needed>20000)warnings.push({message:'Conteúdo excede 20000 px; divida a ficha em outros documentos.'});return {height:doc.pageHeight,requiredHeight:needed,warnings};}
export function expandContent(doc,{skills=[]}={}){const warnings=[];for(const b of doc.blocks.slice().sort((a,b)=>a.y-b.y)){if(b.bindingIssue)continue;const required=requiredHeight(b,doc,skills);if(['text','profile','ability','rituals','ritualPart'].includes(b.type))b.autoFit=false;if(required>b.h){const bottom=b.y+b.h,delta=Math.min(4000,required)-b.h;b.h+=delta;for(const other of doc.blocks)if(other!==b&&other.y>=bottom-1&&other.x<b.x+b.w&&other.x+other.w>b.x)other.y+=delta;if(required>4000)warnings.push({id:b.id,message:'Divida este bloco: o conteúdo exige mais de 4000 px.'});}}doc.pageHeight=Math.max(pageHeight(doc),Math.min(20000,Math.max(...doc.blocks.map(b=>b.y+b.h))+80));return {height:doc.pageHeight,warnings};}
